import {ACTIVITIES,MOLECULES,ATOM_TARGETS,SEPARATIONS,FORMULA_MASS,defaultDiscoveryState,renderDiscovery,checkDiscovery} from './discoveries.js';
import {WORLDS, LESSONS, getLesson, TOPICS_GCSE} from './content.js';
import {ELEMENTS,ELEMENT_ROWS,F_BLOCK,ELEMENT_BY_SYMBOL,LAB_ITEMS,lookupReaction,EQUATIONS,atomBalance} from './chemistry.js';
const SAVE_KEY='hero-academy-chemistryquest-v1';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultHero=(name='Hero')=>({name,completed:[],stars:0,assisted:[],labFound:[],balanced:[],history:[],workshopSolved:[]});
function readStore(){
 try{const x=JSON.parse(localStorage.getItem(SAVE_KEY));if(x&&x.version===1&&Array.isArray(x.heroes)&&x.heroes.length&&x.heroes.length<=12)return x;}catch{}
 return {version:1,active:0,year:4,reducedMotion:false,heroes:[defaultHero()]};
}
let store=readStore();const hero=()=>store.heroes[store.active]||store.heroes[0];
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(store));}catch{}}
const SPECIALS={'Y4-02':{kind:'heat'},'Y5-03':{kind:'mix',target:'dissolve'},'Y5-07':{kind:'mix',target:'reaction'},'Y7-02':{kind:'element',target:'Fe'},'Y9-04':{kind:'balance',eq:0},'Y10-07':{kind:'balance',eq:3},'Y11-07':{kind:'rf',target:0.5}};
const ui={page:'home',lessonId:null,step:'learn',choice:null,feedback:'',help:false,attempts:0,levelYear:store.year||4,labA:'water',labB:'salt',labPrediction:null,labResult:null,labMode:'all',selectedElement:'O',elementSearch:'',eqIndex:0,coeff:[],eqFeedback:'',temperature:20,specialValue:-10,specialA:'water',specialB:'salt',specialCoeffs:[1,1,1],...defaultDiscoveryState()};
const main=$('main');
function pip(){return `<svg class="pip-svg" viewBox="0 0 140 170" role="img" aria-label="Pip the friendly robot"><ellipse cx="70" cy="157" rx="48" ry="8" fill="#78b49f" opacity=".4"/><path d="M70 30V17" stroke="#14353b" stroke-width="7" stroke-linecap="round"/><circle cx="70" cy="13" r="9" fill="#ef733e" stroke="#14353b" stroke-width="3"/><rect x="19" y="29" width="102" height="85" rx="25" fill="#f6d46c" stroke="#14353b" stroke-width="5"/><rect x="32" y="48" width="76" height="51" rx="17" fill="#14353b"/><ellipse cx="52" cy="71" rx="9" ry="12" fill="#a9f6db"/><ellipse cx="88" cy="71" rx="9" ry="12" fill="#a9f6db"/><path d="M59 87q11 10 22 0" stroke="#a9f6db" fill="none" stroke-width="4" stroke-linecap="round"/><rect x="35" y="111" width="70" height="43" rx="16" fill="#efb44c" stroke="#14353b" stroke-width="5"/><path d="M70 120l4 9 10 1-7 7 2 10-9-5-9 5 2-10-7-7 10-1z" fill="#fff7d4"/><path d="M26 120l-13 16m101-16 13 16" stroke="#14353b" stroke-width="9" stroke-linecap="round"/><path d="M53 153v9m34-9v9" stroke="#14353b" stroke-width="10" stroke-linecap="round"/></svg>`;}
function heroArt(){return `<svg class="hero-svg" viewBox="0 0 180 220" role="img" aria-label="Your superhero"><ellipse cx="89" cy="209" rx="65" ry="9" fill="#6f9a86" opacity=".38"/><path d="M49 92L15 180L60 157h69l38 23-36-88" fill="#f6d46c"/><rect x="59" y="85" width="62" height="93" rx="22" fill="#ec7540" stroke="#14353b" stroke-width="5"/><path d="M70 170l-5 28m44-28 7 28" stroke="#14353b" stroke-width="24" stroke-linecap="round"/><path d="M58 112L32 148m90-36 25 36" stroke="#ec7540" stroke-width="19" stroke-linecap="round"/><circle cx="90" cy="53" r="37" fill="#eab79a" stroke="#14353b" stroke-width="4"/><path d="M56 44q34-30 70 0v18H56z" fill="#14353b"/><ellipse cx="77" cy="55" rx="5" ry="8" fill="#d9eee1"/><ellipse cx="103" cy="55" rx="5" ry="8" fill="#d9eee1"/><path d="M79 72q11 11 22 0" fill="none" stroke="#14353b" stroke-width="3" stroke-linecap="round"/><path d="M90 107l6 13 14 2-10 10 2 14-12-7-12 7 2-14-10-10 14-2z" fill="#f6d46c"/></svg>`;}
function wrap(content){return `<section class="panel">${content}</section>`;}
function btn(text,action,variant='secondary',extra=''){return `<button class="btn btn-${variant}" data-action="${esc(action)}" ${extra}>${text}</button>`;}
function notice(text,warning=false){return `<div class="callout ${warning?'warn':''}">${text}</div>`;}
function countForYear(y){return LESSONS.filter(l=>l.year===y&&hero().completed.includes(l.id)).length;}
function worldCard(w){const n=countForYear(w.year);return `<button class="world-card ${ui.levelYear===w.year?'selected':''}" style="border-top:7px solid ${w.colour}" data-action="world:${w.year}"><span class="year">Year ${w.year} · ${w.year<=6?'Key Stage 2':w.year<=9?'Key Stage 3':'GCSE'}</span><span class="world-icon" aria-hidden="true">${w.icon}</span><strong>${esc(w.name)}</strong><span class="small">${n}/10 quests</span><div class="progress"><div style="width:${n*10}%"></div></div></button>`;}
function renderHome(){
 const done=hero().completed.length;
 return `${wrap(`<div class="hero-scene"><div class="hero-copy"><div class="eyebrow">The Elemental Adventure</div><h1>CHEMISTRYQUEST</h1><p class="subtitle">Explore. Experiment. Save the worlds. Learn chemistry from Year 4 to GCSE.</p><div class="btn-row">${btn('🗺️ Play adventure','map','primary')}${btn('🧪 Try the lab','lab','dark')}</div></div><div class="hero-figures">${heroArt()}${pip()}</div></div><div class="stat-grid"><div class="stat"><strong>${done}/80</strong><span>Quests restored</span></div><div class="stat"><strong>⭐ ${hero().stars}</strong><span>Stars earned</span></div><div class="stat"><strong>8</strong><span>Worlds to explore</span></div></div>`)}${wrap(`<div class="eyebrow">Choose your year</div><h2>Pick any world</h2><p class="small">Start where you feel comfortable. Every year and quest is unlocked. Older learners can revisit the basics.</p><div class="world-grid">${WORLDS.map(worldCard).join('')}</div>`)}${wrap(`<h2>Explore more</h2><div class="world-grid"><button class="world-card" data-action="nav:workshop"><span class="world-icon">🔬</span><strong>Discovery workshop</strong><span>Six hands-on investigations</span></button><button class="world-card" data-action="nav:elements"><span class="world-icon">⚛️</span><strong>118 elements</strong><span>Explore the full periodic table</span></button><button class="world-card" data-action="nav:equations"><span class="world-icon">⚖️</span><strong>Balance equations</strong><span>Keep every atom accounted for</span></button></div>`)} `;
}
function renderMap(){
 const w=WORLDS.find(w=>w.year===ui.levelYear)||WORLDS[0];const lessons=LESSONS.filter(l=>l.year===ui.levelYear);const n=countForYear(w.year);
 return `${wrap(`<div class="map-head"><div><div class="eyebrow">Year ${w.year} · ${w.year<=6?'Primary':w.year<=9?'Key Stage 3':'GCSE'}</div><h1>${w.icon} ${esc(w.name)}</h1><p class="subtitle">${esc(w.story)} <strong>${n} of 10</strong> places restored.</p></div>${btn('Change world','home','secondary')}</div><div class="progress"><div style="width:${n*10}%"></div></div><div class="quest-map"><p class="tagline">🗺️ YOUR ADVENTURE PATH · Tap any stop</p><div class="quest-track">${lessons.map((l,i)=>`<button class="quest ${hero().completed.includes(l.id)?'done':''}" data-action="lesson:${esc(l.id)}"><span class="q-figure">${hero().completed.includes(l.id)?'🌟':['🏡','🌿','⚗️','🧊','🌻','💎','🧪','🌈','🌳','🏰'][i]}</span><strong>${esc(l.title)}</strong><span class="tag">${hero().completed.includes(l.id)?'✓ Restored':`Stop ${i+1}`}</span></button>`).join('')}</div></div>`)}${wrap(`<h2>Other adventures</h2><div class="world-grid">${WORLDS.filter(x=>x.year!==w.year).map(worldCard).join('')}</div>`)} `;
}
function playStep(id){ui.lessonId=id;ui.step='learn';ui.feedback='';ui.help=false;ui.attempts=0;ui.choice=null;ui.specialValue=-10;ui.specialA='water';ui.specialB='salt';ui.specialCoeffs=[1,1,1];ui.page='lesson';render();}
function lessonBar(lesson){return `<div class="stage"><span class="node ${ui.step==='learn'?'active':'done'}">1 Discover</span><span class="node ${ui.step==='practice'?'active':['challenge','complete'].includes(ui.step)?'done':''}">2 Try it</span><span class="node ${ui.step==='challenge'?'active':ui.step==='complete'?'done':''}">3 Save it</span></div>`;}
function specialMarkup(l){
 const spec=SPECIALS[l.id];let art='',prompt='',hint='';
 if(spec.kind==='heat'){
  prompt='Heat the ice so that it melts. Change the temperature.';
  art=`<label class="field" for="special-heat">🌡️ Temperature: <strong id="special-heat-label">${ui.specialValue}°C</strong></label><input id="special-heat" type="range" min="-20" max="30" step="10" value="${ui.specialValue}" style="width:100%;min-height:50px"><div class="reactor-zone" style="font-size:65px"><span id="special-heat-icon">${ui.specialValue<=0?'🧊':'💧'}</span></div>`;
  hint='At normal pressure, water is liquid above about 0°C.';
 }else if(spec.kind==='mix'){
  prompt=spec.target==='dissolve'?'Make a solution in the virtual lab.':'Make bubbles by choosing the reacting virtual materials.';
  const items=LAB_ITEMS.filter(([k])=>['water','salt','sand','oil','sugar','vinegar','bicarbonate'].includes(k));
  art=`<div class="selector-row"><div><label class="field" for="special-a">First material</label><select id="special-a">${selectOpts(items,ui.specialA)}</select></div><div><label class="field" for="special-b">Second material</label><select id="special-b">${selectOpts(items,ui.specialB)}</select></div></div><div class="reactor-zone"><span style="font-size:53px">${spec.target==='dissolve'?'💧':'🫧'} ⚗️</span><span class="small">Virtual only</span></div>`;
  hint=spec.target==='dissolve'?'Try dissolving salt in water.':'Which pair from the lesson makes carbon dioxide bubbles?';
 }else if(spec.kind==='element'){
  prompt='Find iron in the element tiles.';
  art=`<div class="choices">${['O','Fe','H','Cu','Na','S'].map(sym=>`<button class="${ui.specialValue===sym?'selected':''}" data-action="special-element:${sym}">${esc(sym)} · ${esc(ELEMENT_BY_SYMBOL[sym].name)}</button>`).join('')}</div>`;
  hint='Iron has the symbol Fe, from its Latin name ferrum.';
 }else if(spec.kind==='balance'){
  const eq=EQUATIONS[spec.eq];prompt=`Balance this virtual reaction: ${eq.name}.`;
  art=`<div class="equation">${eq.terms.map(([formula,side],i)=>`${i>0?(side!==eq.terms[i-1][1]?' <b>→</b> ':' <b>+</b> '):''}<span class="formula-piece"><label class="small" for="special-coeff-${i}">${esc(formula)}</label><select id="special-coeff-${i}" class="coeff" data-special-coeff="${i}" aria-label="Coefficient of ${esc(formula)}">${[1,2,3,4,5,6].map(n=>`<option ${ui.specialCoeffs[i]===n?'selected':''}>${n}</option>`).join('')}</select><b>${esc(formula)}</b></span>`).join('')}</div>`;
  hint=eq.hint;
 }else if(spec.kind==='rf'){
  prompt='A dye moves 3 cm while the solvent front moves 6 cm. What is the Rf value?';
  art=`<label class="field" for="special-rf">Calculate Rf = 3 ÷ 6</label><input id="special-rf" type="number" min="0" max="1" step="0.01" inputmode="decimal" value="${ui.specialValue>=0&&ui.specialValue<=1?ui.specialValue:''}" placeholder="Your answer, e.g. 0.5" style="min-height:53px;border:2px solid #b5cbc0;border-radius:12px;padding:10px;max-width:220px;width:100%">`;
  hint='Divide the distance travelled by the dye by the distance travelled by the solvent front.';
 }
 return `<div class="eyebrow">Hands-on final challenge</div><h2>${esc(prompt)}</h2>${art}${ui.feedback==='correct'?`<div class="feedback" role="status">✅ You did it! ${esc(l.why)}</div><div class="btn-row">${btn('Restore this place ⭐','next-step','primary')}</div>`:`<div class="btn-row">${btn('✨ Check experiment','special-check','primary')}${btn('💡 Help','hint','secondary')}</div>${ui.feedback==='wrong'?`<div class="feedback warn" role="status">${ui.help?esc(hint):'Try again, or ask Pip for help.'}</div>`:''}`}${btn('🔊 Hear','speak','secondary')}`;
}
function checkSpecial(){
 if(ui.feedback==='correct'||ui.step!=='challenge')return;
 const spec=SPECIALS[ui.lessonId];if(!spec)return;
 let okay=false;
 if(spec.kind==='heat')okay=Number(ui.specialValue)>0;
 if(spec.kind==='mix')okay=lookupReaction(ui.specialA,ui.specialB)?.type===spec.target;
 if(spec.kind==='element')okay=ui.specialValue===spec.target;
 if(spec.kind==='balance'){const eq=EQUATIONS[spec.eq];okay=atomBalance(eq,ui.specialCoeffs.slice(0,eq.terms.length)).balanced;}
 if(spec.kind==='rf')okay=Math.abs(Number(ui.specialValue)-spec.target)<0.01;
 ui.feedback=okay?'correct':'wrong';if(!okay)ui.attempts++;render();
}
function renderLesson(){const l=getLesson(ui.lessonId);if(!l)return renderMap();const world=WORLDS.find(w=>w.year===l.year);
 const header=`<div class="eyebrow">${esc(world.name)} · Stop ${l.number}/10</div><h1>${esc(l.title)}</h1>${lessonBar(l)}`;
 const aside=`<div class="lesson-art"><div class="big-icon">${world.icon}</div>${pip()}<strong>“You can try again!”</strong><span class="small">No lives lost. No timer.</span></div>`;
 let body='';
 if(ui.step==='learn')body=`<div class="eyebrow">Learn</div><h2>Discover the idea</h2><p style="font-size:19px">${esc(l.teach)}</p><p class="tagline">Mission · ${esc(l.topic)}</p><div class="btn-row">${btn('🔊 Hear','speak','secondary')}${btn('▶️ Try it','next-step','primary')}</div>`;
 if(['practice','challenge'].includes(ui.step)){
  const idx=ui.step==='practice'?0:1,q=l.questions[idx];
  body=`<div class="eyebrow">${idx===0?'Practice':'Final challenge'}</div><h2>${idx===0?'Make a prediction':'Help restore the world!'}</h2><p class="question">${esc(q.prompt)}</p><div class="answers">${q.options.map((x,i)=>`<button class="answer ${ui.choice===i?ui.feedback==='correct'?'correct':'incorrect':''}" data-action="answer:${i}" ${ui.feedback==='correct'?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(x)}</button>`).join('')}</div>${ui.feedback==='correct'?`<div class="feedback" role="status">✅ Great science! ${esc(l.why)}</div><div class="btn-row">${btn(idx===0?'Next challenge →':'Restore this place ⭐','next-step','primary')}</div>`:ui.feedback==='wrong'?`<div class="feedback warn" role="status">💡 Not quite. ${ui.help?esc(l.teach):'Try another answer, or ask Pip for help.'}</div>`:''}<div class="btn-row">${ui.feedback!=='correct'?btn('💡 Help','hint','secondary'):''}${btn('🔊 Hear','speak','secondary')}</div>`;
 }
 if(ui.step==='challenge'&&SPECIALS[l.id])body=specialMarkup(l);
 if(ui.step==='complete'){
  const was=hero().completed.includes(l.id);body=`<div class="eyebrow">Quest complete!</div><h2>🌟 ${esc(l.title)} restored</h2><p>You helped ${esc(world.name)} shine. ${esc(l.why)}</p><div class="stat">⭐ ${hero().stars} stars · ${was?'Saved progress':'New mission completed'}</div><div class="btn-row">${btn('🗺️ Back to map','map','primary')}${btn('🧪 Explore the lab','lab','secondary')}${btn('🔁 Replay','replay','secondary')}</div>`;
 }
 return wrap(`<div class="lesson-shell"><div class="lesson-card">${header}${body}</div>${aside}</div><div class="btn-row">${btn('← Map','map','secondary')}</div>`);
}
function completeLesson(){const l=getLesson(ui.lessonId);if(!l)return;if(!hero().completed.includes(l.id)){hero().completed.push(l.id);hero().stars+=30;hero().history.push({id:l.id,assisted:ui.help||ui.attempts>0,date:new Date().toISOString()});if(ui.help||ui.attempts>0)hero().assisted.push(l.id);save();}ui.step='complete';}
function speak(){if(!('speechSynthesis'in window)){ui.feedback='voice';render();return;}const l=getLesson(ui.lessonId);const text=l?(ui.step==='learn'?l.teach:ui.step==='complete'?l.why:l.questions[ui.step==='practice'?0:1].prompt):'Welcome to Hero Academy ChemistryQuest.';window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.85;const v=window.speechSynthesis.getVoices().find(v=>v.lang.toLowerCase()==='en-gb'&&/female|susan|serena|kate|siri|libby/i.test(v.name))||window.speechSynthesis.getVoices().find(v=>v.lang.toLowerCase()==='en-gb');if(v)u.voice=v;window.speechSynthesis.speak(u);}
function selectOpts(items,selected){return items.map(([value,label])=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`).join('');}
function mixVisual(result){
 const left=LAB_ITEMS.find(x=>x[0]===ui.labA)?.[1]||ui.labA;
 const right=LAB_ITEMS.find(x=>x[0]===ui.labB)?.[1]||ui.labB;
 const mode=result?.found?result.type:'waiting';
 const bubble=mode==='reaction'?'○ ｡ ◦ ○ ｡':mode==='dissolve'?'· • · • ·':mode==='mixture'?'◌ ◌ ◌':'?';
 const caption=mode==='reaction'?'NEW SUBSTANCES':mode==='dissolve'?'SOLUTION':mode==='mixture'?'PHYSICAL MIXTURE':'PREDICT FIRST';
 return `<div class="reactor-zone" aria-label="Virtual illustration of selected substances and predicted result"><div class="input-beaker"><span class="flask">⚗️</span><span>${esc(left)}</span></div><div class="flow-arrow">＋</div><div class="input-beaker"><span class="flask">⚗️</span><span>${esc(right)}</span></div><div class="flow-arrow">→</div><div class="reactor-beaker ${mode}"><div class="reaction-bubbles">${bubble}</div><div class="reactor-liquid"></div><span class="caption-reaction">${caption}</span></div></div>`;
}
function renderLab(){const items=LAB_ITEMS.filter(x=>ui.labMode==='all'||(ui.labMode==='elements'?!['water','salt','sand','oil','sugar','colour','vinegar','bicarbonate'].includes(x[0]):['water','salt','sand','oil','sugar','colour','vinegar','bicarbonate'].includes(x[0])));
 const result=ui.labResult;return `${wrap(`<div class="eyebrow">Virtual laboratory</div><h1>🧪 Reaction Lab</h1><p class="subtitle">Choose two substances, predict the result, and reveal the science. <strong>A model, not a real experiment.</strong></p>${notice('⚠️ Never mix real chemicals because of something shown here. Reactions may require special conditions and supervision; this simulator shows only curated examples.',true)}<div class="btn-row"><button class="btn ${ui.labMode==='all'?'btn-dark':'btn-secondary'}" data-action="labmode:all">All</button><button class="btn ${ui.labMode==='everyday'?'btn-dark':'btn-secondary'}" data-action="labmode:everyday">Everyday</button><button class="btn ${ui.labMode==='elements'?'btn-dark':'btn-secondary'}" data-action="labmode:elements">Elements</button></div><div class="activity-grid" style="margin-top:17px"><div class="lesson-card"><h2>What will happen?</h2><div class="selector-row"><div><label class="field" for="labA">First substance</label><select id="labA">${selectOpts(items,ui.labA)}</select></div><div><label class="field" for="labB">Second substance</label><select id="labB">${selectOpts(items,ui.labB)}</select></div></div><p class="small">Some pairs make mixtures; others can react in appropriate conditions. Not every pair is modelled.</p>${mixVisual(result)}<p class="field">Your prediction</p><div class="choices">${[['dissolve','💧 Dissolves'],['mixture','🫙 Mixture'],['reaction','✨ New substances']].map(([k,v])=>`<button class="${ui.labPrediction===k?'selected':''}" data-action="predict:${k}">${v}</button>`).join('')}</div><div class="btn-row">${btn('🔎 Reveal result','reveal','primary',ui.labPrediction?'':'disabled')}</div>${result?`<div class="reveal" role="status"><h3>${result.found?result.right?'🌟 Great prediction!':'💡 Let’s investigate':'🔬 Not in this simulator yet'}</h3><p>${esc(result.detail)}</p>${result.equation?`<div class="equation">${esc(result.equation)}</div>`:''}${result.found?`<p class="small">${result.type==='dissolve'?'This is dissolving (a physical process).':result.type==='mixture'?'This is a physical mixture.':'This models a chemical change.'}</p>`:''}</div>`:''}</div><div class="lesson-card"><div class="eyebrow">Pip's science tip</div>${pip()}<h3>Mixing ≠ reacting</h3><p>Two substances can form a mixture without forming something new. A reaction rearranges atoms into new substances.</p><p class="small">You have identified ${hero().labFound.length} of the ${12} modelled pairs.</p>${btn('💧 Particle Playground','particle','secondary')}</div></div>`)}${wrap(renderParticle())}`;
}
function renderParticle(){const t=ui.temperature;const state=t<=0?'solid':t>=100?'gas':'liquid';const particles=Array.from({length:32},(_,i)=>{const col=i%8,row=Math.floor(i/8);let x,y;if(state==='solid'){x=12+col*10.5;y=56+row*10;}else if(state==='liquid'){x=5+((i*37)%89);y=58+((i*19)%34);}else{x=4+((i*37)%91);y=4+((i*41)%86);}return `<span class="particle ${state}" style="left:${x}%;top:${y}%"></span>`;}).join('');
 return `<h2>💧 Particle Playground</h2><p>Change the temperature and see a <em>simplified</em> model of water particles. At normal pressure, melting and boiling occur near 0°C and 100°C.</p><div class="activity-grid"><div><label class="field" for="temperature">Water temperature: <strong id="temperature-label">${t}°C</strong></label><input id="temperature" type="range" min="-20" max="120" step="10" value="${t}" style="width:100%;min-height:48px"><h3 id="water-state">${state==='solid'?'🧊 Solid ice':state==='liquid'?'💧 Liquid water':'☁️ Water vapour'}</h3><p class="small">A visual teaching model, not a molecular dynamics calculation. Boundaries and pressure effects are simplified.</p></div><div class="particle-stage" id="particle-stage" aria-label="Model of ${state} water particles">${particles}</div></div>`;
}
function renderElements(){const sel=ELEMENT_BY_SYMBOL[ui.selectedElement]||ELEMENTS[7];const q=ui.elementSearch.trim().toLowerCase();let cells='';for(let r=0;r<7;r++)for(let c=0;c<18;c++){let sym=ELEMENT_ROWS[r][c];cells+=sym?elementButton(sym):'<span aria-hidden="true"></span>';}
 const rows=F_BLOCK.map((r,i)=>`<div style="grid-column:1/-1;margin-top:${i===0?12:3}px;display:grid;grid-template-columns:repeat(14,minmax(48px,1fr));gap:4px;">${r.map(elementButton).join('')}</div>`).join('');
 const results=q?`<div class="world-grid">${ELEMENTS.filter(e=>e.symbol.toLowerCase().includes(q)||e.name.toLowerCase().includes(q)||String(e.number)===q).map(e=>`<button class="world-card" style="min-height:95px" data-action="element:${e.symbol}"><span class="tagline">${e.number} · ${e.family}</span><strong>${esc(e.symbol)} — ${esc(e.name)}</strong></button>`).join('')||'No matching element yet.'}</div>`:`<p class="small">Tap an element tile to discover its name, group and usual physical state. Swipe the table sideways on a phone.</p><div class="periodic-scroll"><div class="ptable" role="group" aria-label="Periodic table of 118 elements">${cells}${rows}</div></div>`;
 return `${wrap(`<div class="eyebrow">118 chemical elements</div><h1>⚛️ Element Explorer</h1><p class="subtitle">Every element has its own proton number. Explore the whole periodic table.</p><label class="field" for="search-elements">Find an element</label><input class="field" id="search-elements" type="search" placeholder="Search name, symbol or number" value="${esc(ui.elementSearch)}" style="max-width:350px;border:2px solid #cbd6cf;border-radius:12px;padding:11px"><div class="activity-grid" style="margin-top:16px"><div>${results}</div><div class="element-detail" aria-live="polite"><span class="eyebrow">Atomic number ${sel.number}</span><strong>${esc(sel.symbol)}</strong><h2>${esc(sel.name)}</h2><p><b>Family:</b> ${esc(sel.family)}</p><p><b>Period:</b> ${sel.period} · <b>Group:</b> ${sel.group||'f-block'}</p><p><b>State near room temperature:</b> ${esc(sel.state)}</p><p class="small">For very heavy synthetic elements, properties may be unknown or predicted.</p><div class="btn-row">${btn('🧪 Try a virtual mix','lab','primary')}</div></div></div>`)} `;
}
function elementButton(symbol){const e=ELEMENT_BY_SYMBOL[symbol];return `<button class="elem ${e.state.replaceAll(' ','-')} ${ui.selectedElement===symbol?'matched':''}" title="${esc(e.name)}" aria-label="${esc(e.name)}, atomic number ${e.number}" data-action="element:${e.symbol}"><span class="atomic">${e.number}</span><b>${esc(e.symbol)}</b><small>${esc(e.name)}</small></button>`;}
function makeEquationMarkup(eq){let out='',lastSide=1;eq.terms.forEach(([formula,side],i)=>{if(i>0)out+=side!==lastSide?' <strong>→</strong> ':' <strong>+</strong> ';out+=`<span class="formula-piece"><label class="small" for="coeff-${i}">Number for ${esc(formula)}<span class="hide">Coefficient</span></label><select class="coeff" id="coeff-${i}" data-coeff="${i}" aria-label="Coefficient of ${esc(formula)}">${[1,2,3,4,5,6].map(n=>`<option ${ui.coeff[i]===n?'selected':''}>${n}</option>`).join('')}</select><b>${esc(formula)}</b></span>`;lastSide=side;});return out;}
function renderEquations(){const eq=EQUATIONS[ui.eqIndex];const totals=atomBalance(eq,ui.coeff.length===eq.terms.length?ui.coeff:eq.terms.map(()=>1));return `${wrap(`<div class="eyebrow">GCSE puzzle workshop</div><h1>⚖️ Equation Workshop</h1><p class="subtitle">Balance atoms to repair the city bridges. Change the big numbers, never the small numbers in the formula.</p><div class="activity-grid"><div class="lesson-card"><label class="field" for="equation-pick">Choose a puzzle</label><select id="equation-pick" class="field" style="border:2px solid #cbd6cf;border-radius:12px;padding:11px">${EQUATIONS.map((e,i)=>`<option value="${i}" ${i===ui.eqIndex?'selected':''}>${esc(e.name)} ${hero().balanced.includes(i)?'✓':''}</option>`).join('')}</select><h2 style="margin-top:18px">${esc(eq.name)}</h2><div class="equation" id="formula-equation">${makeEquationMarkup(eq)}</div><div class="balance-counts">${Object.keys({...totals.left,...totals.right}).map(s=>`<span>${esc(s)}: <b>${totals.left[s]||0}</b> before · <b>${totals.right[s]||0}</b> after</span>`).join('')}</div><div class="btn-row">${btn('✅ Check balance','check-balance','primary')}${btn('💡 Help','balance-hint','secondary')}</div>${ui.eqFeedback?`<div class="feedback ${ui.eqFeedback==='balanced'?'':'warn'}" role="status">${ui.eqFeedback==='balanced'?'⭐ Balanced! The atoms are conserved. Chemists usually use the smallest whole-number coefficients.':ui.eqFeedback==='hint'?esc(eq.hint):'Not balanced yet. Count each element on both sides.'}</div>`:''}</div><div class="lesson-card">${pip()}<h3>How it works</h3><p>The total number of atoms of each element must match on both sides.</p><p>Use the selectors to choose coefficients from 1 to 6, then check.</p><p class="small">Puzzles restored: ${hero().balanced.length}/${EQUATIONS.length}</p></div></div>`)} `;
}
function renderGrownups(){return `${wrap(`<div class="eyebrow">Adults & teachers</div><h1>⚙️ Learning and settings</h1><p class="subtitle">Progress lives only in this browser. This version does not connect to a school or ChoreQuest account.</p><div class="adult-grid"><div class="lesson-card"><h2>Heroes</h2><label class="field" for="hero-choice">Current hero</label><select id="hero-choice" class="field" style="border:2px solid #cbd6cf;border-radius:12px;padding:10px;width:100%">${store.heroes.map((h,i)=>`<option value="${i}" ${i===store.active?'selected':''}>${esc(h.name)}</option>`).join('')}</select><label class="field" for="hero-name">Add local hero (optional)</label><input id="hero-name" type="text" maxlength="24" placeholder="First name or nickname" style="padding:12px;border:2px solid #cbd6cf;border-radius:12px;max-width:100%;width:100%"><div class="btn-row">${btn('Add hero','add-hero','secondary',store.heroes.length>=12?'disabled':'')}${btn('Export save','export','secondary')}${btn('Import save','import','secondary')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><p class="small">Maximum 12 local hero profiles. No names are transmitted by this game. Your browser may erase local data.</p></div><div class="lesson-card"><h2>Accessibility</h2><p>Speech is optional and starts only when someone taps <b>Hear</b>. The browser chooses a British English voice when available; the exact voice is not guaranteed.</p><label class="field"><input id="motion" type="checkbox" ${store.reducedMotion?'checked':''}> Reduce animation</label><p class="small">All questions are untimed. Touch, mouse and keyboard work; no dragging is required. Helpful attempts are recorded separately.</p><p><strong>${hero().completed.length}</strong> quests · <strong>${hero().assisted.length}</strong> quests completed with help or retry.</p></div></div>`)}${wrap(`<h2>Curriculum map</h2><p>England science programme of study, with a <strong>suggested</strong> Year 7–11 teaching sequence. Y6 reinforces Year 5 materials and enquiry because there is no separate statutory chemistry topic in Y6. This is a prototype: one micro-lesson per topic, not evidence of full curriculum or GCSE exam-board coverage.</p><label class="field" for="curriculum-year">Explore the lessons</label><select id="curriculum-year" style="padding:11px;border:2px solid #cbd6cf;border-radius:12px;margin-bottom:12px">${WORLDS.map(w=>`<option value="${w.year}" ${w.year===ui.levelYear?'selected':''}>Year ${w.year}</option>`).join('')}</select><div class="curriculum-list">${LESSONS.filter(l=>l.year===ui.levelYear).map(l=>`<div><strong>${esc(l.id)} · ${esc(l.title)}</strong><span class="small"> — ${esc(l.topic)} ${hero().completed.includes(l.id)?'✓':''}</span></div>`).join('')}</div>${ui.levelYear>=10?`<h3>AQA GCSE Chemistry topic headings</h3><p class="small">${TOPICS_GCSE.map(esc).join(' · ')}</p>`:''}<p class="small">Virtual practicals do not replace AQA or other awarding-body supervised required practical activities. GCSE Separate/Combined and Foundation/Higher variants, exam-board objectives, and teacher validation need further content development.</p>`)} `;
}
function renderWorkshop(){return wrap(renderDiscovery(ui,esc,btn,hero().workshopSolved||[]));}
function render(){
 const views={home:renderHome,map:renderMap,lesson:renderLesson,lab:renderLab,elements:renderElements,equations:renderEquations,workshop:renderWorkshop,grownups:renderGrownups};main.innerHTML=(views[ui.page]||renderHome)();
 document.querySelectorAll('.tabs button').forEach(b=>{if(b.dataset.nav===ui.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 $('stars').textContent='⭐ '+hero().stars;$('profile-badge').textContent='🦸 '+hero().name;
}
function navigate(page){if(!['home','map','lab','elements','equations','workshop','grownups'].includes(page))return;ui.page=page;ui.labResult=null;ui.eqFeedback='';render();window.scrollTo({top:0,behavior:store.reducedMotion?'auto':'smooth'});}
function revealLab(){const r=lookupReaction(ui.labA,ui.labB);ui.labResult=r?{...r,found:true,right:r.type===ui.labPrediction}:{found:false,right:false,detail:'This pair has not been modelled. We cannot infer whether there is a reaction, mixture, or safety risk. Explore a different pair.'};if(r&&r.type===ui.labPrediction){const key=[ui.labA,ui.labB].sort().join(':');if(!hero().labFound.includes(key)){hero().labFound.push(key);hero().stars+=5;save();}}render();}
function checkBalance(){const eq=EQUATIONS[ui.eqIndex];const b=atomBalance(eq,ui.coeff);ui.eqFeedback=b.balanced?'balanced':'wrong';if(b.balanced&&!hero().balanced.includes(ui.eqIndex)){hero().balanced.push(ui.eqIndex);hero().stars+=10;save();}render();}
function download(name,text){const blob=new Blob([text],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),4000);}
function validImport(x){return x&&x.version===1&&Array.isArray(x.heroes)&&x.heroes.length>0&&x.heroes.length<=12&&x.heroes.every(h=>typeof h.name==='string'&&h.name.length<=24&&Array.isArray(h.completed)&&Array.isArray(h.assisted)&&Array.isArray(h.labFound)&&Array.isArray(h.balanced)&&Number.isFinite(h.stars)&&h.stars>=0&&h.stars<1000000);}
function action(command){
 if(command.startsWith('nav:'))return navigate(command.slice(4));
 if(command.startsWith('world:')){const y=Number(command.slice(6));if(!WORLDS.some(w=>w.year===y))return;ui.levelYear=y;store.year=y;save();return navigate('map');}
 if(command.startsWith('lesson:'))return playStep(command.slice(7));
 if(command.startsWith('element:')){ui.selectedElement=command.slice(8);return render();}
 if(command.startsWith('labmode:')){ui.labMode=command.slice(8);ui.labA=ui.labMode==='elements'?'iron':'water';ui.labB=ui.labMode==='elements'?'oxygen':'salt';ui.labPrediction=null;ui.labResult=null;return render();}
 if(command.startsWith('predict:')){ui.labPrediction=command.slice(8);ui.labResult=null;return render();}
 if(command.startsWith('special-element:')){ui.specialValue=command.slice(16);return render();}
 if(command.startsWith('discovery:')){const name=command.slice(10);if(!ACTIVITIES.some(x=>x.id===name))return;Object.assign(ui,defaultDiscoveryState(),{discovery:name});return render();}
 if(command.startsWith('atom-plus:')||command.startsWith('atom-minus:')){const symbol=command.split(':')[1];if(!['H','O','C','N'].includes(symbol))return;const inc=command.startsWith('atom-plus:')?1:-1;ui.atomCounts[symbol]=Math.min(8,Math.max(0,(ui.atomCounts[symbol]||0)+inc));ui.discoveryFeedback=null;return render();}
 if(command.startsWith('answer:')){const l=getLesson(ui.lessonId);if(!l||!['practice','challenge'].includes(ui.step)||ui.feedback==='correct')return;const idx=Number(command.slice(7));const q=l.questions[ui.step==='practice'?0:1];ui.choice=idx;if(idx===q.answer){ui.feedback='correct';}else{ui.feedback='wrong';ui.attempts++;}return render();}
 switch(command){
  case 'home':case 'map':case 'lab':case 'elements':case 'equations':case 'workshop':case 'grownups':return navigate(command);
  case 'check-discovery':{const result=checkDiscovery(ui);ui.discoveryFeedback=result;if(result.ok){if(!Array.isArray(hero().workshopSolved))hero().workshopSolved=[];if(!hero().workshopSolved.includes(result.key)){hero().workshopSolved.push(result.key);hero().stars+=10;save();}}return render();}
  case 'reset-discovery':{const name=ui.discovery;Object.assign(ui,defaultDiscoveryState(),{discovery:name});return render();}
  case 'speak':return speak();
  case 'special-check':return checkSpecial();
  case 'next-step':if(ui.step==='learn')ui.step='practice';else if(ui.step==='practice'&&ui.feedback==='correct')ui.step='challenge';else if(ui.step==='challenge'&&ui.feedback==='correct')completeLesson();ui.feedback='';ui.choice=null;return render();
  case 'hint':ui.help=true;ui.feedback='wrong';return render();
  case 'replay':return playStep(ui.lessonId);
  case 'reveal':if(ui.labPrediction)return revealLab();return;
  case 'particle':return document.getElementById('temperature')?.scrollIntoView({behavior:'smooth'});
  case 'check-balance':return checkBalance();
  case 'balance-hint':ui.eqFeedback='hint';return render();
  case 'export':return download('chemistryquest-heroes.json',JSON.stringify(store,null,2));
  case 'import':return $('import-file')?.click();
  case 'add-hero':{const input=$('hero-name');const name=input?.value?.trim();if(name&&store.heroes.length<12){store.heroes.push(defaultHero(name));store.active=store.heroes.length-1;save();render();}else if(input){input.setCustomValidity('Enter a name (maximum 24 characters).');input.reportValidity();}return;}
 }
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-nav]');if(!b)return;if(b.tagName==='A')e.preventDefault();const cmd=b.dataset.action||(b.dataset.nav?'nav:'+b.dataset.nav:null);if(cmd)action(cmd);});
document.addEventListener('change',e=>{
 const t=e.target;
 if(t.id==='labA'||t.id==='labB'){ui.labA=$('labA').value;ui.labB=$('labB').value;ui.labPrediction=null;ui.labResult=null;render();}
 if(t.id==='equation-pick'){ui.eqIndex=Number(t.value);ui.coeff=EQUATIONS[ui.eqIndex].terms.map(()=>1);ui.eqFeedback='';render();}
 if(t.id==='special-a'||t.id==='special-b'){ui.specialA=$('special-a').value;ui.specialB=$('special-b').value;ui.feedback='';render();}
 if(t.dataset.specialCoeff!==undefined){ui.specialCoeffs[Number(t.dataset.specialCoeff)]=Number(t.value);ui.feedback='';render();}
 if(t.id==='special-rf'){ui.specialValue=Number(t.value);ui.feedback='';}
 if(t.dataset.coeff!==undefined){ui.coeff[Number(t.dataset.coeff)]=Number(t.value);ui.eqFeedback='';render();}
 const selectDiscovery={ 'molecule-pick':'molecule','atom-target':'atomTarget','separation-pick':'separation','separation-method':'method','compound-pick':'compound' };
 if(selectDiscovery[t.id]){ui[selectDiscovery[t.id]]=t.value;ui.discoveryFeedback=null;if(t.id==='molecule-pick')ui.atomCounts={H:0,O:0,C:0,N:0};if(t.id==='atom-target'){const atom=ATOM_TARGETS.find(x=>x.symbol===t.value);ui.protons=atom?.protons||1;ui.electrons=atom?.protons||1;ui.neutrons=atom?.protons||1;}if(t.id==='compound-pick'){ui.mass=(FORMULA_MASS.find(x=>x.id===t.value)?.mr||18)*2;ui.molesGuess=2;}render();}
 if(ui.page==='workshop'&&['temperature','concentration','surfaceArea','spot-distance','solvent-distance','rf-guess','moles-mass','moles-guess','protons','neutrons','electrons'].includes(t.id)){return render();}
 if(t.id==='curriculum-year'){ui.levelYear=Number(t.value);render();}
 if(t.id==='hero-choice'){store.active=Number(t.value);save();render();}
 if(t.id==='motion'){store.reducedMotion=t.checked;save();document.documentElement.classList.toggle('reduce-motion',t.checked);}
 if(t.id==='import-file'&&t.files?.[0]){const file=t.files[0];if(file.size>200000)return alert('This save file is too large.');file.text().then(s=>{let incoming;try{incoming=JSON.parse(s);}catch{return alert('Could not read this file.');}if(!validImport(incoming))return alert('Not a compatible ChemistryQuest backup.');store=incoming;store.active=Math.max(0,Math.min(store.heroes.length-1,Number(store.active)||0));save();render();});}
});
document.addEventListener('input',e=>{
 const discoveryInput={protons:'protons',neutrons:'neutrons',electrons:'electrons',temperature:'temperature',concentration:'concentration',surfaceArea:'surfaceArea','spot-distance':'spotDistance','solvent-distance':'solventDistance','rf-guess':'rfGuess','moles-mass':'mass','moles-guess':'molesGuess'};
 if(ui.page==='workshop'&&discoveryInput[e.target.id]){const key=discoveryInput[e.target.id];const num=Number(e.target.value);ui[key]=['rfGuess','molesGuess'].includes(key)?e.target.value:Number.isFinite(num)?Math.max(0,Math.min(1000,num)):0;ui.discoveryFeedback=null;if(e.target.type==='range'){e.target.previousElementSibling?.querySelector('output')&&(e.target.previousElementSibling.querySelector('output').textContent=e.target.value+(e.target.id==='temperature'?'°C':'×'));}return;}
 if(e.target.id==='special-heat'){ui.specialValue=Number(e.target.value);$('special-heat-label').textContent=ui.specialValue+'°C';$('special-heat-icon').textContent=ui.specialValue<=0?'🧊':'💧';}
 if(e.target.id==='special-rf'){ui.specialValue=Number(e.target.value);}
 if(e.target.id==='temperature'){ui.temperature=Number(e.target.value);const fresh=document.createElement('div');fresh.innerHTML=renderParticle();$('temperature-label').textContent=ui.temperature+'°C';$('water-state').textContent=fresh.querySelector('#water-state').textContent;$('particle-stage').innerHTML=fresh.querySelector('#particle-stage').innerHTML;$('particle-stage').setAttribute('aria-label',fresh.querySelector('#particle-stage').getAttribute('aria-label'));}
 if(e.target.id==='search-elements'){const val=e.target.value;const caret=e.target.selectionStart;ui.elementSearch=val;render();const input=$('search-elements');input?.focus();try{input?.setSelectionRange(caret,caret);}catch{}}
});
ui.coeff=EQUATIONS[0].terms.map(()=>1);render();